H.background();
const theo = Math.max(0.001, P.theoretical);
const actual = Math.max(0, P.actual);
const pct = (actual / theo) * 100;
const shown = Math.min(actual, theo);
H.text("Percent yield = (actual / theoretical) x 100%", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Compares what you really recovered to the stoichiometric maximum; in practice it is below 100%.", 24, 52, { color: H.colors.sub, size: 13 });

const bx = 120, by = 110, bw = 150, bh = 240;
H.rect(bx, by, bw, bh, { stroke: H.colors.grid, width: 2, radius: 4 });
const settle = 1 - Math.exp(-t * 1.2);
const fillFrac = Math.min(1, shown / theo) * (0.96 + 0.04 * Math.sin(t * 2.5)) * settle;
const fillH = bh * Math.max(0, Math.min(1, fillFrac));
H.rect(bx + 2, by + bh - fillH, bw - 4, fillH, { fill: H.colors.accent });
H.line(bx - 14, by, bx + bw + 14, by, { color: H.colors.warn, width: 2, dash: [6, 4] });
H.text("theoretical max", bx + bw + 18, by + 4, { color: H.colors.warn, size: 12 });
const ly = by + bh - bh * Math.min(1, shown / theo);
H.line(bx - 14, ly, bx + bw + 14, ly, { color: H.colors.good, width: 2 });
H.text("actual", bx + bw + 18, ly + 4, { color: H.colors.good, size: 12 });

H.text("Theoretical = " + theo.toFixed(2) + " g", 480, 150, { color: H.colors.warn, size: 14, weight: 700 });
H.text("Actual = " + actual.toFixed(2) + " g", 480, 184, { color: H.colors.good, size: 14, weight: 700 });
const pcol = pct > 100 ? H.colors.warn : H.colors.accent2;
H.text("Percent yield = " + pct.toFixed(1) + " %", 480, 230, { color: pcol, size: 20, weight: 700 });
if (pct > 100) H.text("(>100% means impure product or error)", 480, 256, { color: H.colors.warn, size: 12 });
else H.text("lost to side reactions, transfer, purification", 480, 256, { color: H.colors.sub, size: 12 });

const gx = 480, gy = 300, gw = 320, gh = 26;
H.rect(gx, gy, gw, gh, { stroke: H.colors.grid, width: 1, radius: 6 });
const gwid = gw * Math.min(1, pct / 100) * settle;
H.rect(gx, gy, Math.max(0, gwid), gh, { fill: H.colors.accent2, radius: 6 });
H.text("0%", gx, gy + gh + 16, { color: H.colors.sub, size: 11 });
H.text("100%", gx + gw - 26, gy + gh + 16, { color: H.colors.sub, size: 11 });
